INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('1', 'chena-hot-springs', 'Chena Hot Springs Resort', 65.0518, -146.051, 'AK', 'soakalaska', 106, 106, 20, NULL, NULL, 'Drive-up', 'Resort', 'Year-round', '7:00 AM - 11:45 PM daily', 'Required', NULL, 'Ample parking at resort', 'Alaska''s only full-service hot spring resort, located 56 miles northeast of Fairbanks. Features indoor and outdoor mineral pools, an ice museum, lodging, and aurora viewing in winter.', 'Weekday mornings for fewer crowds. Winter nights for northern lights.', 'The outdoor rock lake is the highlight. Stay overnight for aurora viewing from the hot springs.', 0, NULL, NULL, NULL, 1214, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Chena_Hot_Springs%2C_Alaska', 'Chena Hot Springs is an unincorporated community and hot spring resort in the Fairbanks North Star Borough, Alaska, United States, 56.5 miles (90.9 km) northeast of Fairbanks near the Chena River State Recreation Area. The resort makes use of the first low-temperature binary geothermal power plant built in Alaska, and is working on several alternative energy projects, including production and use of hydrogen and vegetable oil for fuel. The resort is conducting collaborative experiments in greenhouse production of vegetables with the University of Alaska Fairbanks Agricultural and Forestry Experiment Station.', '{"site_no":"15490000","site_name":"MONUMENT C AT CHENA HOT SPRINGS AK","distance_miles":0.2,"site_type":"ST","site_elevation_ft":null,"water_quality":[{"parameter":"Temperature, water","value":1.5,"unit":"deg C","date":"1971-09-29","media":"Water"},{"parameter":"Specific conductance","value":66,"unit":"uS/cm @25C","date":"1971-09-29","media":"Water"},{"parameter":"pH","value":7.4,"unit":"std units","date":"1971-09-29","media":"Water"},{"parameter":"Alkalinity","value":25,"unit":"mg/l CaCO3","date":"1971-09-29","media":"Water"},{"parameter":"Total dissolved solids","value":43,"unit":"mg/l","date":"1971-09-29","media":"Water"}],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=15490000"}', NULL);
INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('2', 'alyeska-nordic-spa', 'Alyeska Nordic Spa', 60.9646, -149.098, 'AK', 'soakalaska', NULL, NULL, 75, NULL, NULL, 'Drive-up', 'Developed', 'Year-round', '11:00 AM - 8:00 PM', 'Required', NULL, NULL, 'Alaska''s first Nordic spa, set in the Chugach Mountains at Alyeska Resort in Girdwood. Features 50,000 sq ft of indoor-outdoor hydrotherapy pools, cold plunges, saunas, and steam rooms.', 'Weekday afternoons for a quieter experience.', 'Book in advance. Stay at Alyeska Resort for spa package deals.', 0, NULL, NULL, NULL, 482, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Alyeska_Resort', 'Alyeska Resort is a ski resort in the Girdwood area of Anchorage, Alaska, approximately 30 miles (48 km) from downtown Anchorage. Mount Alyeska is part of the Chugach mountain range and the Alyeska Resort is the largest ski area in the state. It includes the mountaintop Mt. Alyeska Roundhouse, which is listed on the National Register of Historic Places.', '{"site_no":"605750149062401","site_name":"SA01000216BAAA1  011","distance_miles":0.4,"site_type":"GW","site_elevation_ft":280,"water_quality":[],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=605750149062401"}', NULL);
INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('3', 'pilgrim-hot-springs', 'Pilgrim Hot Springs', 65.0936, -164.9239, 'AK', 'soakalaska', 130, 130, 10, NULL, NULL, 'Drive-up', 'Primitive', 'Summer', NULL, NULL, NULL, NULL, 'A historic geothermal oasis on the Seward Peninsula near Nome. Surrounded by cottonwood trees and tundra, the springs were once a Catholic mission and orphanage. Road accessible in summer only.', 'Summer months when the road is passable.', 'The road from Nome requires a high-clearance vehicle. Check road conditions before heading out.', 0, NULL, NULL, NULL, 16, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Pilgrim_Hot_Springs', 'Pilgrim Hot Springs is a ghost town in the interior of the Seward Peninsula of northwestern Arctic Alaska. Also known as Kruzgamepa, Kruzgamepa Springs and Unaatuq. It is located on the southeast bank of the Kruzgamepa River, about 8 miles (13 km) south of milepost 65 of the Kougarok Road, on the traditional lands of the Kauweramiut, also known as the People of Kauwerak, also known as people of the Village of Mary''s Igloo and their descendants.', '{"site_no":"650535164551001","site_name":"KC00403136DDDA1S","distance_miles":0.1,"site_type":"SP","site_elevation_ft":25,"water_quality":[{"parameter":"Temperature, water","value":69,"unit":"deg C","date":"1915-09-02","media":"Water"},{"parameter":"Alkalinity","value":17,"unit":"mg/l CaCO3","date":"1915-09-02","media":"Water"},{"parameter":"Total dissolved solids","value":5960,"unit":"mg/l","date":"1915-09-02","media":"Water"}],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=650535164551001"}', NULL);
