INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('5', 'baranof-warm-springs', 'Baranof Warm Springs', 57.0894, -134.8331, 'AK', 'soakalaska', 120, 120, 0, NULL, NULL, 'Boat-in', 'Community', 'Summer', NULL, NULL, NULL, NULL, 'A small community on Baranof Island in Southeast Alaska, accessible only by boat or floatplane. Features natural hot springs with a bathhouse and a picturesque lake setting. No roads or ferry service.', 'Summer for boat access. Not accessible in winter.', 'The Baranof Cross-Island Trail from Sitka ends here. Bring all supplies.', 0, NULL, NULL, NULL, 184, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Baranof_Warm_Springs%2C_Alaska', 'Baranof Warm Springs is a small, primarily seasonally-occupied community located in the city and borough of Sitka, Alaska, on the eastern side of Baranof Island, from which it likely derives its name, in the Alexander Archipelago. It is occasionally referred to simply as Baranof. Baranof Warm Springs is located at 57°05′22″N 134°49′59″W.', '{"site_no":"570520134502501","site_name":"CD05506624ADCB1S","distance_miles":0.3,"site_type":"SP","site_elevation_ft":75,"water_quality":[{"parameter":"Alkalinity","value":67,"unit":"mg/l CaCO3","date":"1972-03-23","media":"Water"},{"parameter":"Total dissolved solids","value":190,"unit":"mg/l","date":"1972-03-23","media":"Water"},{"parameter":"Temperature, water","value":41,"unit":"deg C","date":"1972-03-23","media":"Water"},{"parameter":"Specific conductance","value":242,"unit":"uS/cm @25C","date":"1972-03-23","media":"Water"},{"parameter":"pH","value":9.4,"unit":"std units","date":"1972-03-23","media":"Water"}],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=570520134502501"}', NULL);
