INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('11', 'manley-hot-springs', 'Manley Hot Springs', 65.0078, -150.6267, 'AK', 'soakalaska', NULL, NULL, 5, NULL, NULL, 'Drive-up', 'Community', 'Year-round', 'By appointment', NULL, NULL, NULL, 'A small community at the end of the Elliott Highway, about 150 miles northwest of Fairbanks. The hot springs are on private property and accessible by appointment only. The town has a rich gold rush history.', 'Year-round, but call ahead for an appointment.', 'Call ahead to arrange access. The road is paved most of the way but the last stretch can be rough.', 0, NULL, NULL, NULL, 413, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"site_no":"90229000017","site_name":"MANLEY COMMUNITY WATER SYSTEM","distance_miles":0,"site_type":"FA-WDS","site_elevation_ft":null,"water_quality":[],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=90229000017"}', NULL);
INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('12', 'serpentine-hot-springs', 'Serpentine Hot Springs', 65.858, -164.71, 'AK', 'soakalaska', NULL, NULL, 0, NULL, NULL, 'Bush plane', 'Primitive', 'Year-round', NULL, NULL, NULL, NULL, 'Remote hot springs in the Bering Land Bridge National Preserve on the Seward Peninsula. Accessible primarily by bush plane or snowmachine. Features granite tors and Arctic tundra landscape.', 'Summer for bush plane access. Winter for snowmachine.', 'A backcountry permit may be required from the National Park Service. Weather can change rapidly.', 0, NULL, NULL, NULL, 427, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"site_no":"655111164414701","site_name":"KB00502912BCBB1S","distance_miles":0.5,"site_type":"SP","site_elevation_ft":450,"water_quality":[{"parameter":"Temperature, water","value":68,"unit":"deg C","date":"1976-07-12","media":"Water"},{"parameter":"Specific conductance","value":4590,"unit":"uS/cm @25C","date":"1976-07-12","media":"Water"},{"parameter":"pH","value":7.8,"unit":"std units","date":"1976-07-12","media":"Water"},{"parameter":"Alkalinity","value":55,"unit":"mg/l CaCO3","date":"1976-07-12","media":"Water"},{"parameter":"Total dissolved solids","value":2600,"unit":"mg/l","date":"1976-07-12","media":"Water"}],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=655111164414701"}', NULL);
INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('13', 'tolovana-hot-springs', 'Tolovana Hot Springs', 65.274, -148.847, 'AK', 'soakalaska', NULL, NULL, 40, NULL, NULL, 'Hike-in', 'Community', 'Year-round', NULL, NULL, NULL, NULL, 'Managed by BLM, these hot springs are in the Tolovana River valley north of Fairbanks. Features three cabins for overnight stays and natural soaking pools. An 8-mile trail leads to the springs.', 'Year-round. Winter trail access is popular with skiers and snowmachiners.', 'Cabin reservations required for overnight. Day use fee is $40/person. Trail can be challenging in shoulder seasons.', 0, NULL, NULL, NULL, 1014, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"site_no":"651627148505001","site_name":"FB00500607    1S","distance_miles":0.1,"site_type":"SP","site_elevation_ft":1000,"water_quality":[{"parameter":"Specific conductance","value":2090,"unit":"uS/cm @25C","date":"1962-07-01","media":"Water"},{"parameter":"pH","value":7.7,"unit":"std units","date":"1962-07-01","media":"Water"},{"parameter":"Alkalinity","value":40,"unit":"mg/l CaCO3","date":"1962-07-01","media":"Water"},{"parameter":"Total dissolved solids","value":1180,"unit":"mg/l","date":"1962-07-01","media":"Water"}],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=651627148505001"}', '{"osm_id":11361079541,"osm_name":"Middle Tub (Bento Box)","osm_url":"https://www.openstreetmap.org/node/11361079541","match_distance_miles":0.17,"tags":{"bath:type":"hot_spring","name":"Middle Tub (Bento Box)","natural":"hot_spring"},"nearby":{"access_roads":[{"type":"path","name":"Murphy Dome to Tolavana Hot Springs Winter Trail","surface":null,"access":null},{"type":"path","name":null,"surface":null,"access":null},{"type":"path","name":"Tolovana Hot Springs Trail","surface":null,"access":null}],"parking":[],"trails":[{"type":"path","name":"Murphy Dome to Tolavana Hot Springs Winter Trail","surface":null,"sac_scale":null},{"type":"path","name":null,"surface":null,"sac_scale":null},{"type":"path","name":"Tolovana Hot Springs Trail","surface":null,"sac_scale":null}],"buildings":[{"type":"cabin","name":"Frame Cabin"},{"type":"cabin","name":"Cedar Cabin"},{"type":"cabin","name":"Log Cabin"}],"amenities":[{"type":"tourism:yes","name":"Tolovana Hot Springs"}]}}');
INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('14', 'circle-hot-springs', 'Circle Hot Springs', 65.4833, -144.6342, 'AK', 'soakalaska', NULL, NULL, 0, NULL, NULL, 'Drive-up', 'Community', 'Year-round', NULL, NULL, NULL, NULL, 'Historic hot spring and former resort in the Yukon-Koyukuk Census Area, 131 miles from Fairbanks via the Steese Highway. The resort is closed but the hot spring pool remains in usable condition. Rich in gold rush history and aurora viewing folklore.', 'Winter for northern lights. Summer for road access.', 'The resort buildings are condemned but the pool is still soakable. The site has a colorful history including ghost stories. Bring everything you need.', 0, NULL, NULL, NULL, 925, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"site_no":"652857144381801","site_name":"FA00801534BACA1S","distance_miles":0.2,"site_type":"SP","site_elevation_ft":900,"water_quality":[{"parameter":"Alkalinity","value":144,"unit":"mg/l CaCO3","date":"1976-07-10","media":"Water"},{"parameter":"Temperature, water","value":56.5,"unit":"deg C","date":"1976-07-10","media":"Water"},{"parameter":"Total dissolved solids","value":819,"unit":"mg/l","date":"1976-07-10","media":"Water"},{"parameter":"Specific conductance","value":1180,"unit":"uS/cm @25C","date":"1976-07-10","media":"Water"},{"parameter":"pH","value":7.2,"unit":"std units","date":"1976-07-10","media":"Water"}],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=652857144381801"}', NULL);
