INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('16', 'white-sulphur-hot-springs', 'White Sulphur Springs', 57.8061, -136.3392, 'AK', 'soakalaska', NULL, NULL, 0, NULL, NULL, 'Boat-in', 'Community', 'Year-round', NULL, NULL, NULL, NULL, 'A US Forest Service recreation site on the north shore of Bertha Bay on Chichagof Island. Features a restored bathhouse with indoor and outdoor warm pools. A rustic cabin is available for rent. Named for the white sulfur deposits.', 'Year-round. Summer for easier boat access.', 'Reserve the Forest Service cabin in advance. Bring all supplies. Short boat ride from Pelican.', 0, NULL, NULL, NULL, 52, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"site_no":"574825136202501","site_name":"CD04705609    1S","distance_miles":0.1,"site_type":"SP","site_elevation_ft":15,"water_quality":[{"parameter":"Temperature, water","value":44,"unit":"deg C","date":"1915-06-28","media":"Water"},{"parameter":"Alkalinity","value":56,"unit":"mg/l CaCO3","date":"1915-06-28","media":"Water"},{"parameter":"Total dissolved solids","value":276,"unit":"mg/l","date":"1915-06-28","media":"Water"}],"usgs_url":"https://waterdata.usgs.gov/nwis/inventory?site_no=574825136202501"}', NULL);
INSERT OR REPLACE INTO springs (id, slug, name, lat, lng, state, site, temp_f, temperature_f, fee, fee_amount_usd, fees, access_type, development, season, hours, clothing, clothing_policy, parking, description, best_time, insider_tips, has_post, region, nearby_town, distance_to_town_mi, elevation_ft, fs_road, road_condition, trailhead_lat, trailhead_lon, reservation_required, reservation_url, seasonal_open, seasonal_close, seasonal_notes, cell_coverage, cell_service, ada_accessible, dog_policy, pool_count, water_flow, image_url, chemistry, chemistry_details, chemistry_level, chemistry_sampled_on, chemistry_source, source_temperature_c, wikipedia_url, wikipedia_summary, usgs_json, osm_json) VALUES ('17', 'goddard-hot-springs', 'Goddard Hot Springs', 56.8465, -135.3798, 'AK', 'soakalaska', 153, 153, 0, NULL, NULL, 'Boat-in', 'Community', 'Year-round', NULL, NULL, NULL, NULL, 'Historic hot springs on the outer coast of Baranof Island, about 16 miles south of Sitka. Features two cedar bathhouses with covered stainless steel tubs fed by geothermal springs. Free public access with campsites nearby.', 'Year-round. Summer for calmer seas.', 'Accessible by boat or floatplane from Sitka. Tom Young Memorial Cabin available for overnight. Watch for black flies in summer.', 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"site_no":"565005135222001","site_name":"CD05806317CCCA1S","distance_miles":0.9,"site_type":"SP","site_elevation_ft":60,"water_quality":[{"parameter":"Temperature, water","value":63,"unit":"deg C","date":"1962-12-01","media":"Water"},{"parameter":"Alkalinity","value":26,"unit":"mg/l CaCO3","date":"1962-12-01","media":"Water"},{"parameter":"Total dissolved solids","value":5010,"unit":"mg/l","date":"1962-12-01","media":"Water"},{"parameter":"Specific conductance","value":9060,"unit":"uS/cm @25C","date":"1962-12-01","media":"Water"},{"parameter"